package com.projetointer.backend.enrollment;
import com.projetointer.backend.catalog.ClassOffering; import com.projetointer.backend.user.User; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="enrollments",uniqueConstraints=@UniqueConstraint(columnNames={"student_id","class_offering_id"}))
public class Enrollment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private User student; @ManyToOne(optional=false) private ClassOffering classOffering; @Enumerated(EnumType.STRING) private Status status=Status.CONFIRMED; private LocalDateTime registeredAt=LocalDateTime.now(); protected Enrollment(){} public Enrollment(User s,ClassOffering c){student=s;classOffering=c;} public enum Status{PENDING,CONFIRMED,CANCELLED} public Long getId(){return id;} public User getStudent(){return student;} public ClassOffering getClassOffering(){return classOffering;} public Status getStatus(){return status;} public LocalDateTime getRegisteredAt(){return registeredAt;} public void cancel(){status=Status.CANCELLED;} public void restore(){status=Status.CONFIRMED;} }
